namespace SirketMotoru.Isletim;

public static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Şirket Yönetim Merkezi</title>
<style>
:root{color-scheme:dark;--bg:#07101c;--p:#0d1a2b;--p2:#122238;--line:#263a55;--text:#edf5ff;--muted:#94a9c5;--accent:#46e0ad;--blue:#67aaff;--bad:#ff6e7f;--warn:#ffd166;--good:#45e29f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#142841,#07101c 48%);color:var(--text);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select{font:inherit}.shell{max-width:1480px;margin:auto;padding:16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.brand{font-weight:850;letter-spacing:.06em}.brand small{display:block;color:var(--muted);font-weight:500;letter-spacing:0}.status{display:flex;gap:8px;align-items:center;color:var(--muted)}.dot{width:9px;height:9px;border-radius:50%;background:var(--bad)}.dot.ok{background:var(--good);box-shadow:0 0 10px var(--good)}.card{background:rgba(13,26,43,.96);border:1px solid var(--line);border-radius:15px;padding:14px}.login{max-width:430px;margin:10vh auto}.hidden{display:none!important}label{display:block;color:var(--muted);margin:8px 0 4px}input,select{width:100%;padding:9px;border:1px solid var(--line);border-radius:9px;background:#071321;color:var(--text)}button{cursor:pointer;border:0;border-radius:9px;padding:9px 12px;background:var(--accent);color:#032117;font-weight:750}button.secondary{background:#213754;color:var(--text)}button.danger{background:var(--bad);color:white}button.small{padding:6px 9px;font-size:12px}button:disabled{opacity:.4;cursor:not-allowed}.full{width:100%;margin-top:12px}.notice{padding:10px;border:1px solid var(--line);border-radius:9px;color:var(--muted);margin-top:10px}.notice.good{color:var(--good);border-color:#23634e}.notice.bad{color:var(--bad);border-color:#713542}.metrics{display:grid;grid-template-columns:repeat(6,minmax(125px,1fr));gap:9px;margin-bottom:12px}.metric{background:var(--p);border:1px solid var(--line);border-radius:12px;padding:11px}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{font-size:18px}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.tab{border:1px solid var(--line);background:#0a1728;color:var(--muted);border-radius:999px}.tab.active{background:var(--accent);color:#032117;border-color:var(--accent)}.page{display:none}.page.active{display:block}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.stack{display:grid;gap:11px}.item{background:var(--p2);border:1px solid var(--line);border-radius:12px;padding:12px}.item h3{margin:0 0 5px;font-size:15px}.item p{margin:4px 0;color:var(--muted)}.row{display:flex;align-items:center;justify-content:space-between;gap:9px}.tags{display:flex;gap:5px;flex-wrap:wrap;margin:6px 0}.tag{border:1px solid var(--line);border-radius:999px;padding:3px 7px;color:var(--muted);font-size:12px}.tag.good{color:var(--good);border-color:#28634e}.tag.bad{color:var(--bad);border-color:#743744}.tag.warn{color:var(--warn);border-color:#6c592c}.formrow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:9px}.formrow.three{grid-template-columns:repeat(3,minmax(0,1fr))}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:780px}th,td{padding:8px 6px;border-bottom:1px solid var(--line);text-align:left}th{font-size:12px;color:var(--muted)}td input{min-width:90px}.right{text-align:right}.sectiontitle{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.sectiontitle h2{font-size:16px;margin:0}.banner{border:1px solid #6d5929;color:var(--warn);background:#211d12;border-radius:11px;padding:10px;margin-bottom:12px}.empty{color:var(--muted);padding:14px;text-align:center}.tx{display:grid;grid-template-columns:85px 100px 1fr auto;gap:7px;padding:7px 0;border-bottom:1px solid var(--line);font-size:12px}.positive{color:var(--good)}.negative{color:var(--bad)}#toast{position:fixed;right:16px;bottom:16px;max-width:430px;background:#10243b;border:1px solid var(--line);border-radius:11px;padding:11px;z-index:5}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,1fr)}.grid,.grid3{grid-template-columns:1fr 1fr}.formrow{grid-template-columns:1fr 1fr}}@media(max-width:620px){.shell{padding:9px}.metrics,.grid,.grid3,.formrow,.formrow.three{grid-template-columns:1fr}.top{align-items:flex-start}.tx{grid-template-columns:60px 1fr}.tx span:nth-child(3){grid-column:1/-1}}
</style>
</head>
<body>
<div class="shell">
  <div class="top">
    <div class="brand">ŞİRKET YÖNETİM MERKEZİ<small>İzleme · Fiyatlandırma · Yayın Yönetimi · Altyapı · Banka</small></div>
    <div class="status"><span id="dot" class="dot"></span><span id="conn">BAĞLANTI YOK</span><button id="logout" class="secondary small hidden">Çıkış</button></div>
  </div>

  <section id="loginView" class="card login">
    <h1>Şirket hesabına giriş</h1>
    <p style="color:var(--muted)">Bu ekran kod yazmaz. Yalnız kendi sunucunun ilan ettiği hizmet, uygulama ve protokolleri yönetir.</p>
    <label>Kullanıcı adı</label><input id="username" autocomplete="username">
    <label>Parola</label><input id="password" type="password" autocomplete="current-password">
    <button id="login" class="full">Giriş yap</button>
    <div id="loginMsg" class="notice">Geçici hesap bilgileri motor konsolunda görünür.</div>
  </section>

  <main id="app" class="hidden">
    <div class="banner"><b>Temel kural:</b> Yeni hizmet, uygulama özelliği veya özel protokol burada oluşturulamaz. Önce şirket sunucusunda kodlanıp <code>sirketTanitim</code> manifestinde ilan edilmelidir.</div>
    <section id="metrics" class="metrics"></section>
    <nav id="tabs" class="tabs">
      <button class="tab active" data-tab="overview">Genel</button>
      <button class="tab" data-tab="services">Hizmetler</button>
      <button class="tab" data-tab="apps">Uygulamalar</button>
      <button class="tab" data-tab="infra">Altyapı</button>
      <button class="tab" data-tab="bank">Banka</button>
      <button class="tab" data-tab="protocols">Protokoller</button>
      <button class="tab" data-tab="contracts">Sözleşmeler</button>
      <button class="tab" data-tab="security">Hesap</button>
    </nav>

    <section id="overview" class="page active stack"></section>
    <section id="services" class="page card"></section>
    <section id="apps" class="page stack"></section>
    <section id="infra" class="page card"></section>
    <section id="bank" class="page stack"></section>
    <section id="protocols" class="page stack"></section>
    <section id="contracts" class="page stack"></section>
    <section id="security" class="page card"></section>
  </main>
</div>
<div id="toast" class="hidden"></div>
<script>
const $=s=>document.querySelector(s), fmt=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(n||0)), money=n=>fmt(n)+' TL';
let state=null, timer=null;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(text,ok=true){const e=$('#toast');e.textContent=text;e.className=ok?'notice good':'notice bad';setTimeout(()=>e.classList.add('hidden'),3500);e.classList.remove('hidden');}
async function request(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{data={basarili:false,aciklama:'Sunucu yanıtı okunamadı.'}}if(!r.ok||data.basarili===false)throw new Error(data.aciklama||'İşlem başarısız.');return data;}
async function login(){try{await request('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');await refresh();timer=setInterval(refresh,3000);}catch(e){$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad';}}
async function logout(){try{await request('/api/cikis',{});}catch{}clearInterval(timer);location.reload();}
async function refresh(){try{state=await request('/api/durum');$('#dot').classList.add('ok');$('#conn').textContent='MOTORA BAĞLI';render();}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='BAĞLANTI HATASI';if(String(e.message).includes('Oturum')){clearInterval(timer);location.reload();}}}
function render(){const s=state.sirket||{},i=state.isletim||{},k=state.kodTabanliYayinlar||{};$('#metrics').innerHTML=[['Kasa',money(s.kasa)],['Şirket değeri',money(i.sirketDegeri)],['Aktif kullanıcı',fmt(i.toplamAboneSayisi)],['Toplam borç',money(i.toplamBorc)],['Kod kalitesi',fmt(s.kodKalitesiPuani)],['Güvenlik',fmt(s.guvenlikPuani)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');renderOverview(s,i,k);renderServices(k.hizmetler||[]);renderApps(k.uygulamalar||[],i.urunler||[]);renderInfra(state.yatirimMagazasi||[]);renderBank(state.krediPaketleri||[],i.krediler||[]);renderProtocols(k.protokoller||[],state.protokoller||[]);renderContracts(state.sozlesmeTeklifleri||[],i.sozlesmeler||[]);renderSecurity();}
function renderOverview(s,i,k){const events=(state.piyasaOlaylari||[]).map(o=>`<div class="item"><b>${esc(o.baslik)}</b><p>${esc(o.aciklama)}</p><span class="tag warn">Tick ${o.baslangicTicki}-${o.bitisTicki}</span></div>`).join('')||'<div class="empty">Aktif piyasa olayı yok.</div>';const tx=(i.sonIslemler||[]).slice(0,20).map(x=>`<div class="tx"><span>T${x.tickNumarasi}</span><span>${esc(x.islemTuru)}</span><span>${esc(x.aciklama)}</span><b class="${Number(x.tutar)>=0?'positive':'negative'}">${money(x.tutar)}</b></div>`).join('')||'<div class="empty">İşlem kaydı yok.</div>';$('#overview').innerHTML=`<div class="grid"><div class="card"><div class="sectiontitle"><h2>Şirket durumu</h2><span class="tag ${s.bagliMi?'good':'bad'}">${s.bagliMi?'SUNUCU BAĞLI':'SUNUCU KAPALI'}</span></div><div class="grid3"><div class="item"><p>Performans</p><b>${fmt(s.performansPuani)}</b></div><div class="item"><p>İtibar</p><b>${fmt(s.itibarPuani)}</b></div><div class="item"><p>Güvenilirlik</p><b>${fmt(s.guvenilirlikPuani)}</b></div><div class="item"><p>Kredi notu</p><b>${fmt(i.krediNotu)}</b></div><div class="item"><p>Ekosistem</p><b>${fmt(i.ekosistemPuani)}</b></div><div class="item"><p>Abonelik geliri</p><b>${money(i.toplamAbonelikGeliri)}</b></div></div></div><div class="card"><div class="sectiontitle"><h2>Piyasa olayları</h2></div>${events}</div></div><div class="card"><div class="sectiontitle"><h2>Son şirket işlemleri</h2></div>${tx}</div>`;}
function renderServices(list){$('#services').innerHTML=`<div class="sectiontitle"><h2>Sunucunun ilan ettiği hizmetler</h2><span class="tag">Fiyat ve ticari aktiflik yönetilebilir</span></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th>Sürüm</th><th>Fiyat</th><th>Kapasite</th><th>Uygulama bağı</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${list.map((h,n)=>`<tr><td><b>${esc(h.hizmetKimligi)}</b></td><td>${esc(h.hizmetSurumu)}</td><td><input id="price${n}" type="number" min="0.01" step="0.01" value="${Number(h.birimFiyat)}"></td><td>${fmt(h.azamiEszamanliIs)}</td><td>${h.uygulamalardaKullaniliyor?'<span class="tag good">KULLANILIYOR</span>':'-'}</td><td><span class="tag ${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</span></td><td><button class="small" data-act="price" data-n="${n}">Fiyatı kaydet</button> <button class="small ${h.aktif?'danger':'secondary'}" data-act="service-toggle" data-n="${n}">${h.aktif?'Pasife al':'Aktife al'}</button></td></tr>`).join('')}</tbody></table></div>`;$('#services').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{const h=list[Number(b.dataset.n)];try{if(b.dataset.act==='price')await request('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:Number($('#price'+b.dataset.n).value)});else await request('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif});toast('Hizmet ayarı güncellendi.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderApps(apps,products){$('#apps').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Sunucuda kodlanan uygulamalar</h2><span class="tag">Serbest uygulama oluşturma yok</span></div>${apps.length?apps.map((x,n)=>appCard(x,n,products)).join(''):'<div class="empty">Sunucu henüz uygulama manifesti ilan etmiyor.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Piyasadaki uygulamalar</h2></div>${products.length?products.map((p,n)=>productCard(p,n)).join(''):'<div class="empty">Piyasaya açılmış uygulama yok.</div>'}</div>`;bindApps(apps,products);}
function appCard(x,n,products){const a=x.uygulama,d=x.dogrulama,features=(a.ozellikler||[]).map(o=>`<span class="tag ${o.zorunlu?'good':''}">${esc(o.ozellikKimligi)} → ${esc(o.hizmetKimligi)}</span>`).join('');const errors=(d.hatalar||[]).map(e=>`<p class="negative">• ${esc(e)}</p>`).join('');const deps=(a.bagimliliklar||[]).map(v=>`<span class="tag">${esc(v.sirketKimligi)}/${esc(v.uygulamaKimligi)}</span>`).join('');return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">${esc(a.surum)}</span></h3><p>${esc(a.aciklama)}</p></div><span class="tag ${d.gecerli?'good':'bad'}">${d.gecerli?'STANDARDI GEÇTİ':'EKSİK KOD'}</span></div><div class="tags">${features}</div>${deps?`<p>Uygulama bağlantıları</p><div class="tags">${deps}</div>`:''}${errors}${x.piyasada?`<div class="notice good">Piyasada · Ürün kimliği: ${esc(x.urunKimligi)}</div>`:`<div class="formrow"><label>Model<select id="model${n}"><option value="abonelik">Abonelik</option><option value="kullanim">Kullanım</option><option value="freemium">Freemium</option><option value="lisans">Lisans</option></select></label><label>Abonelik ücreti<input id="sub${n}" type="number" min="0" step="0.01" value="25"></label><label>Kullanım ücreti<input id="use${n}" type="number" min="0" step="0.0001" value="0"></label><button data-act="publish-app" data-n="${n}" ${!d.gecerli||!x.sunucuBagli?'disabled':''}>Piyasaya aç</button></div>`}</div>`;}
function productCard(p,n){return `<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(p.urunAdi)}</h3><p>${esc(p.kategori)} · ${fmt(p.aktifKullaniciSayisi)}/${fmt(p.kullaniciKapasitesi)} kullanıcı</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'DURDURULDU'}</span></div><div class="formrow"><label>Abonelik<input id="psub${n}" type="number" min="0" step="0.01" value="${Number(p.abonelikUcreti)}"></label><label>Kullanım<input id="puse${n}" type="number" min="0" step="0.0001" value="${Number(p.kullanimBasinaUcret)}"></label><label>Kapasite ekle<input id="pcap${n}" type="number" min="100" step="100" value="100"></label><div><button class="small" data-act="product-save" data-n="${n}">Kaydet</button> <button class="small secondary" data-act="product-cap" data-n="${n}">Kapasite al</button> <button class="small ${p.aktif?'danger':'secondary'}" data-act="product-toggle" data-n="${n}">${p.aktif?'Durdur':'Yayına al'}</button></div></div></div>`;}
function bindApps(apps,products){$('#apps').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{try{const n=Number(b.dataset.n);if(b.dataset.act==='publish-app'){const x=apps[n];await request('/api/uygulama/yayinla',{uygulamaKimligi:x.uygulama.uygulamaKimligi,fiyatlandirmaModeli:$('#model'+n).value,abonelikUcreti:Number($('#sub'+n).value),kullanimBasinaUcret:Number($('#use'+n).value)});}else{const p=products[n];if(b.dataset.act==='product-cap')await request('/api/uygulama/kapasite',{urunKimligi:p.urunKimligi,eklenecekKapasite:Number($('#pcap'+n).value)});else await request('/api/uygulama/guncelle',{urunKimligi:p.urunKimligi,abonelikUcreti:Number($('#psub'+n).value),kullanimBasinaUcret:Number($('#puse'+n).value),aktif:b.dataset.act==='product-toggle'?!p.aktif:p.aktif});}toast('Uygulama yönetimi güncellendi.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderInfra(list){$('#infra').innerHTML=`<div class="sectiontitle"><h2>Altyapı ve departman yatırımları</h2><span class="tag">Kod kalitesi satın alınamaz</span></div><div class="grid3">${list.map((x,n)=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><div class="row"><span>Seviye ${x.seviye}/${x.azamiSeviye}</span><b>${money(x.sonrakiMaliyet)}</b></div><button class="full" data-n="${n}" ${x.seviye>=x.azamiSeviye?'disabled':''}>Satın al</button></div>`).join('')}</div>`;$('#infra').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{try{await request('/api/yatirim',{yatirimTuru:list[Number(b.dataset.n)].yatirimTuru});toast('Yatırım tamamlandı.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderBank(packs,loans){$('#bank').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Kredi paketleri</h2><span class="tag">Taksitler motor ticklerinde kesilir</span></div><div class="grid">${packs.map((p,n)=>`<div class="item"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)} - ${money(p.azamiTutar)} · Not ≥ ${p.asgariKrediNotu}</p><label>Tutar<input id="loan${n}" type="number" min="${p.asgariTutar}" max="${p.azamiTutar}" value="${p.asgariTutar}"></label><button class="full" data-n="${n}">Kredi çek</button></div>`).join('')}</div></div><div class="card"><div class="sectiontitle"><h2>Aktif krediler</h2></div>${loans.length?loans.map(l=>`<div class="item"><div class="row"><b>${esc(l.krediTuru)}</b><span>${money(l.kalanBorc)}</span></div><p>${l.kalanTaksit} taksit · Sonraki ödeme tick ${l.sonrakiOdemeTicki} · Gecikme ${l.gecikmeSayisi}</p></div>`).join(''):'<div class="empty">Aktif kredi yok.</div>'}</div>`;$('#bank').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{try{const p=packs[Number(b.dataset.n)];await request('/api/kredi',{krediTuru:p.krediTuru,tutar:Number($('#loan'+b.dataset.n).value)});toast('Kredi kasaya aktarıldı.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderProtocols(declared,market){$('#protocols').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Sunucuda kodlanan özel protokoller</h2></div>${declared.length?declared.map((x,n)=>`<div class="item" style="margin-bottom:9px"><div class="row"><div><h3>${esc(x.protokol.protokolAdi)} <span class="tag">${esc(x.protokol.surum)}</span></h3><p>${esc(x.protokol.aciklama)}</p></div><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'KOD UYUMLU':'HİZMET EKSİK'}</span></div><div class="tags">${(x.protokol.yetkinlikler||[]).map(y=>`<span class="tag">${esc(y.yetkinlikKimligi)} → ${esc(y.hizmetKimligi)}</span>`).join('')}</div>${x.piyasada?`<div class="notice good">Piyasada · ${esc(x.piyasaProtokolKimligi)}</div>`:`<div class="formrow"><label>Lisans<select id="lic${n}"><option value="acik">Açık</option><option value="tek-seferlik">Tek seferlik</option><option value="abonelik">Abonelik</option></select></label><label>Benimseme bedeli<input id="adopt${n}" type="number" min="0" value="0"></label><label>Tick lisansı<input id="tickfee${n}" type="number" min="0" value="0"></label><button data-act="publish-protocol" data-n="${n}" ${!x.gecerli?'disabled':''}>Piyasaya aç</button></div>`}</div>`).join(''):'<div class="empty">Sunucu özel protokol manifesti ilan etmiyor.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Protokol piyasası</h2></div>${market.length?market.map((p,n)=>`<div class="item"><div class="row"><div><b>${esc(p.protokolAdi)} ${esc(p.surum)}</b><p>${esc(p.aciklama)}</p></div><button class="small" data-act="adopt-protocol" data-n="${n}">Benimse</button></div><div class="tags"><span class="tag">${money(p.benimsemeBedeli)}</span><span class="tag">${money(p.tickLisansBedeli)}/tick</span><span class="tag">${fmt((p.benimseyenSirketler||[]).length)} şirket</span></div></div>`).join(''):'<div class="empty">Piyasada protokol yok.</div>'}</div>`;$('#protocols').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{try{const n=Number(b.dataset.n);if(b.dataset.act==='publish-protocol'){const x=declared[n];await request('/api/protokol/yayinla',{protokolKimligi:x.protokol.protokolKimligi,surum:x.protokol.surum,lisansModeli:$('#lic'+n).value,benimsemeBedeli:Number($('#adopt'+n).value),tickLisansBedeli:Number($('#tickfee'+n).value)});}else await request('/api/protokol/benimse',{protokolKimligi:market[n].protokolKimligi});toast('Protokol işlemi tamamlandı.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderContracts(offers,active){$('#contracts').innerHTML=`<div class="card"><div class="sectiontitle"><h2>Açık SLA teklifleri</h2></div>${offers.length?offers.map((o,n)=>`<div class="item"><div class="row"><div><h3>${esc(o.baslik)}</h3><p>${esc(o.kategori)} · ${o.sureTick} tick</p></div><button class="small" data-n="${n}">Kabul et</button></div><div class="tags"><span class="tag good">${money(o.tickOdemesi)}/tick</span><span class="tag bad">${money(o.ihlalCezasi)} ceza</span><span class="tag">K ${o.asgariKalite}</span><span class="tag">P ${o.asgariPerformans}</span><span class="tag">G ${o.asgariGuvenlik}</span><span class="tag">Kap. ${o.gerekliKapasite}</span></div></div>`).join(''):'<div class="empty">Açık teklif yok.</div>'}</div><div class="card"><div class="sectiontitle"><h2>Aktif sözleşmeler</h2></div>${active.length?active.map(s=>`<div class="item"><div class="row"><b>${esc(s.baslik)}</b><span class="tag ${s.aktif?'good':'bad'}">${s.aktif?'AKTİF':'BİTTİ'}</span></div><p>Tick ${s.baslangicTicki}-${s.bitisTicki} · Başarı ${s.basariliTickSayisi} · İhlal ${s.ihlalSayisi}</p></div>`).join(''):'<div class="empty">Sözleşme yok.</div>'}</div>`;$('#contracts').querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{try{await request('/api/sozlesme/kabul',{teklifKimligi:offers[Number(b.dataset.n)].teklifKimligi});toast('Sözleşme kabul edildi.');await refresh();}catch(e){toast(e.message,false);}}));}
function renderSecurity(){$('#security').innerHTML=`<div class="sectiontitle"><h2>Şirket hesabı</h2></div><div class="grid"><div class="item"><h3>Parola değiştir</h3><label>Mevcut parola<input id="oldpass" type="password"></label><label>Yeni parola<input id="newpass" type="password"></label><button id="changePass" class="full">Parolayı değiştir</button></div><div class="item"><h3>Yetki sınırı</h3><p>Bu hesap yalnız kendi şirketinin kasa, banka, yatırım, fiyat, aktiflik, kapasite, sözleşme ve koddan ilan edilen yayınlarını yönetebilir.</p><p>Hizmet veya uygulama kodu yükleme yetkisi yoktur.</p></div></div>`;$('#changePass').addEventListener('click',async()=>{try{await request('/api/parola',{eskiParola:$('#oldpass').value,yeniParola:$('#newpass').value});toast('Parola değiştirildi.');}catch(e){toast(e.message,false);}});}
$('#login').addEventListener('click',login);$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').addEventListener('click',logout);$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.tab));});
request('/api/durum').then(()=>{ $('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');refresh();timer=setInterval(refresh,3000);}).catch(()=>{});
</script>
</body>
</html>
""";
}
